import React, { useState, useEffect } from 'react';
import axios from 'axios';
import AddBook from './AddBook';
import BookCard from './BookCard';
import BookModal from './BookModal';
import SearchBar from './SearchBar';
import FilterPanel from './FilterPanel';

function BookList({ user, showToast }) {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState('');
  const [selectedBook, setSelectedBook] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const fetchBooks = () => {
    const token = localStorage.getItem('token');
    axios.get('http://localhost:5000/api/books', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => setBooks(res.data))
      .catch(() => setError('Failed to fetch books'));
  };

  useEffect(() => {
    fetchBooks();
  }, []);

  const requestBook = async (bookId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post('http://localhost:5000/api/requests', {
        bookId
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (showToast) showToast('Request sent!');
    } catch (err) {
      if (showToast) showToast(err.response?.data?.message || 'Failed to request book');
    }
  };

  const handleAddBook = () => {
    fetchBooks();
  };

  const handleBookClick = (book) => {
    setSelectedBook(book);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedBook(null);
  };

  return (
    <div className="card">
      <h2 className="form-title">Available Books</h2>
      
      {user?.role === 'librarian' && (
        <AddBook onAdd={handleAddBook} showToast={showToast} />
      )}
      
      {error && <div className="alert alert-error">{error}</div>}
      
      <div className="book-grid">
        {books.length === 0 ? (
          <p style={{ textAlign: 'center', color: 'var(--gray-500)', padding: '2rem' }}>
            No books available
          </p>
        ) : (
          books.map(book => (
            <BookCard 
              key={book._id} 
              book={book} 
              user={user} 
              onRequest={requestBook}
              onBookClick={handleBookClick}
            />
          ))
        )}
      </div>
      
      <BookModal 
        book={selectedBook}
        isOpen={isModalOpen}
        onClose={handleCloseModal}
        user={user}
        onRequest={requestBook}
      />
    </div>
  );
}

export default BookList;
